func (q *Queries) RevokeAllRefreshTokensForUser(ctx context.Context, userID pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, revokeAllRefreshTokensForUser, userID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeRefreshToken = `-- name: RevokeRefreshToken :exec
UPDATE auth.refresh_tokens SET revoked_at = NOW()
WHERE id = $1 AND revoked_at IS NULL
`

func (q *Queries) RevokeRefreshToken(ctx context.Context, id pgtype.UUID) error {
	_, err := q.db.Exec(ctx, revokeRefreshToken, id)
	return err
}

const revokeRefreshTokenChain = `-- name: RevokeRefreshTokenChain :execrows
WITH RECURSIVE descendants(rt_id) AS (
    SELECT rt.id FROM auth.refresh_tokens rt WHERE rt.id = $1
    UNION ALL
    SELECT rt.id
    FROM auth.refresh_tokens rt
    JOIN descendants d ON rt.parent_id = d.rt_id
)
UPDATE auth.refresh_tokens SET revoked_at = NOW()
WHERE id IN (SELECT rt_id FROM descendants) AND revoked_at IS NULL
`

// Revokes root_id and every descendant reachable from it via parent_id —
// the whole rotation family, since presenting a consumed token means the
// entire chain is compromised, not just that one token.
func (q *Queries) RevokeRefreshTokenChain(ctx context.Context, id pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, revokeRefreshTokenChain, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const roleInSpace = `-- name: RoleInSpace :one
SELECT role FROM auth.memberships WHERE user_id = $1 AND space_id = $2
`

type RoleInSpaceParams struct {
	UserID  pgtype.UUID
	SpaceID pgtype.UUID
}

// The authorization question, asked as one indexed lookup on the primary
// key. Absent means "not a member", which callers turn into NOT_FOUND
// rather than PERMISSION_DENIED (docs/api/spaces.md §3).
func (q *Queries) RoleInSpace(ctx context.Context, arg RoleInSpaceParams) (string, error) {
	row := q.db.QueryRow(ctx, roleInSpace, arg.UserID, arg.SpaceID)
	var role string
	err := row.Scan(&role)
	return role, err
}

const upsertMembership = `-- name: UpsertMembership :one
INSERT INTO auth.memberships (user_id, space_id, role, granted_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (user_id, space_id) DO UPDATE SET role = EXCLUDED.role, granted_by = EXCLUDED.granted_by
RETURNING user_id, space_id, role, created_at
`

type UpsertMembershipParams struct {
	UserID    pgtype.UUID
	SpaceID   pgtype.UUID
	Role      string
	GrantedBy pgtype.UUID
}

type UpsertMembershipRow struct {
	UserID    pgtype.UUID
	SpaceID   pgtype.UUID
	Role      string
	CreatedAt pgtype.Timestamptz
}

// An upsert because "change Ada to viewer" and "add Ada as viewer" are one
// intent (docs/api/spaces.md §1).
func (q *Queries) UpsertMembership(ctx context.Context, arg UpsertMembershipParams) (UpsertMembershipRow, error) {
	row := q.db.QueryRow(ctx, upsertMembership,
		arg.UserID,
		arg.SpaceID,
		arg.Role,
		arg.GrantedBy,
	)
	var i UpsertMembershipRow
	err := row.Scan(
		&i.UserID,
		&i.SpaceID,
		&i.Role,
		&i.CreatedAt,
	)
	return i, err
}
